module PlayHelper
  def player_result(answer)
    if answer.nil?
      { text: "No answer", css: "play-status--neutral" }
    elsif answer.option.correct?
      { text: "Correct!", css: "play-status--right" }
    else
      { text: "Wrong!", css: "play-status--wrong" }
    end
  end
end
